CREATE TABLE IF NOT EXISTS kv(k TEXT PRIMARY KEY, v TEXT NOT NULL, t INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS topics(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, parent_id INTEGER, from_round INTEGER, t INTEGER NOT NULL, visits INTEGER NOT NULL DEFAULT 0, last_round INTEGER);
CREATE TABLE IF NOT EXISTS rounds(id INTEGER PRIMARY KEY, t INTEGER NOT NULL, topic_id INTEGER, topic TEXT, title TEXT, model TEXT, neurons REAL, ms INTEGER);
CREATE TABLE IF NOT EXISTS turns(id INTEGER PRIMARY KEY AUTOINCREMENT, round_id INTEGER NOT NULL, idx INTEGER, mind TEXT NOT NULL, text TEXT NOT NULL, t INTEGER);
CREATE TABLE IF NOT EXISTS insights(id INTEGER PRIMARY KEY AUTOINCREMENT, round_id INTEGER, t INTEGER, kind TEXT, mind TEXT, title TEXT, text TEXT NOT NULL, topic TEXT);
CREATE TABLE IF NOT EXISTS journal(id INTEGER PRIMARY KEY AUTOINCREMENT, mind TEXT NOT NULL, round_id INTEGER, t INTEGER, text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mind_memory(mind TEXT PRIMARY KEY, summary TEXT NOT NULL, rounds INTEGER NOT NULL DEFAULT 0, t INTEGER);
CREATE TABLE IF NOT EXISTS usage_day(day TEXT PRIMARY KEY, neurons REAL NOT NULL DEFAULT 0, calls INTEGER NOT NULL DEFAULT 0, rounds INTEGER NOT NULL DEFAULT 0, fails INTEGER NOT NULL DEFAULT 0, skips INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_turns_round ON turns(round_id);
CREATE INDEX IF NOT EXISTS idx_ins_kind ON insights(kind,id);
CREATE INDEX IF NOT EXISTS idx_journal_mind ON journal(mind,id);
CREATE TABLE IF NOT EXISTS note_events(id INTEGER PRIMARY KEY AUTOINCREMENT, round_id INTEGER, t INTEGER, mind TEXT NOT NULL, kind TEXT NOT NULL, text TEXT);
CREATE INDEX IF NOT EXISTS idx_note_kind ON note_events(kind,id);
ALTER TABLE turns ADD COLUMN reply_to INTEGER;
ALTER TABLE rounds ADD COLUMN ended TEXT;
CREATE TABLE IF NOT EXISTS lexicon(id INTEGER PRIMARY KEY AUTOINCREMENT, term TEXT NOT NULL, term_key TEXT UNIQUE NOT NULL, meaning TEXT NOT NULL, mind TEXT NOT NULL, round_id INTEGER, t INTEGER, uses INTEGER NOT NULL DEFAULT 0, users TEXT NOT NULL DEFAULT '', last_t INTEGER);
CREATE INDEX IF NOT EXISTS idx_lex_use ON lexicon(uses,id);
CREATE TABLE IF NOT EXISTS grokky_notice(mind TEXT PRIMARY KEY, t INTEGER, round_id INTEGER, kind TEXT, text TEXT);
ALTER TABLE turns ADD COLUMN acts TEXT;
CREATE TABLE IF NOT EXISTS studies(id INTEGER PRIMARY KEY AUTOINCREMENT, mind TEXT NOT NULL, title TEXT NOT NULL, tkey TEXT NOT NULL, notes INTEGER NOT NULL DEFAULT 0, started_t INTEGER, last_t INTEGER, round_id INTEGER, UNIQUE(mind,tkey));
CREATE TABLE IF NOT EXISTS study_notes(id INTEGER PRIMARY KEY AUTOINCREMENT, study_id INTEGER NOT NULL, round_id INTEGER, t INTEGER, mind TEXT, text TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sn_study ON study_notes(study_id,id);
CREATE TABLE IF NOT EXISTS experiments(id INTEGER PRIMARY KEY AUTOINCREMENT, round_id INTEGER, t INTEGER, mind TEXT NOT NULL, kind TEXT NOT NULL, hypothesis TEXT, params TEXT, result TEXT, summary TEXT);
CREATE TABLE IF NOT EXISTS images(id INTEGER PRIMARY KEY AUTOINCREMENT, round_id INTEGER, t INTEGER, mind TEXT NOT NULL, prompt TEXT NOT NULL, caption TEXT, chunks INTEGER NOT NULL DEFAULT 0, bytes INTEGER);
CREATE TABLE IF NOT EXISTS image_chunks(image_id INTEGER NOT NULL, n INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(image_id,n));
CREATE TABLE IF NOT EXISTS image_reactions(image_id INTEGER NOT NULL, mind TEXT NOT NULL, round_id INTEGER, t INTEGER, text TEXT, PRIMARY KEY(image_id,mind));
CREATE TABLE IF NOT EXISTS memories(id INTEGER PRIMARY KEY AUTOINCREMENT, mind TEXT NOT NULL, t INTEGER, round_id INTEGER, kind TEXT, text TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_mem_mind ON memories(mind,id);
CREATE TABLE IF NOT EXISTS self_models(mind TEXT PRIMARY KEY, text TEXT NOT NULL, v INTEGER NOT NULL DEFAULT 1, t INTEGER);
CREATE TABLE IF NOT EXISTS self_notes(id INTEGER PRIMARY KEY AUTOINCREMENT, mind TEXT NOT NULL, round_id INTEGER, t INTEGER, text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mind_state(mind TEXT PRIMARY KEY, place TEXT, activity TEXT, detail TEXT, t INTEGER, round_id INTEGER);

CREATE TABLE IF NOT EXISTS mind_notice(subject TEXT NOT NULL, mind TEXT NOT NULL, t INTEGER, round_id INTEGER, kind TEXT, text TEXT, PRIMARY KEY(subject, mind));
CREATE TABLE IF NOT EXISTS inner_cost(mind TEXT PRIMARY KEY, model_n INTEGER, neurons REAL, t INTEGER, round_id INTEGER);
CREATE TABLE IF NOT EXISTS inner_views(id INTEGER PRIMARY KEY AUTOINCREMENT, mind TEXT NOT NULL, t INTEGER, round_id INTEGER, piece TEXT NOT NULL, label TEXT, excerpt TEXT, conclusion TEXT);
CREATE INDEX IF NOT EXISTS idx_inner_mind ON inner_views(mind,id);
CREATE TABLE IF NOT EXISTS army_missions(id INTEGER PRIMARY KEY AUTOINCREMENT, t INTEGER, round_id INTEGER, lead TEXT NOT NULL, kind TEXT NOT NULL, title TEXT, status TEXT NOT NULL, topic TEXT, findings TEXT, report TEXT, started_t INTEGER, ended_t INTEGER);
CREATE INDEX IF NOT EXISTS idx_army_id ON army_missions(id);
